<?php
namespace ScratchByPHP\Cache;
final class FileCache implements CacheInterface { public function __construct(private string $dir){if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new \RuntimeException('Cache klasörü oluşturulamadı.');} private function p(string $k):string{return rtrim($this->dir,'/\\').'/'.hash('sha256',$k).'.cache';} public function get(string $k,mixed $d=null):mixed{$p=$this->p($k);if(!is_file($p))return $d;$x=@unserialize((string)file_get_contents($p),['allowed_classes'=>true]);if(!is_array($x)||($x['expires']??0)<time()){@unlink($p);return $d;}return $x['value']??$d;} public function set(string $k,mixed $v,int $ttl=60):bool{return file_put_contents($this->p($k),serialize(['expires'=>time()+max(1,$ttl),'value'=>$v]),LOCK_EX)!==false;} public function delete(string $k):bool{$p=$this->p($k);return !is_file($p)||@unlink($p);} public function clear():bool{$ok=true;foreach(glob(rtrim($this->dir,'/\\').'/*.cache')?:[] as $p)$ok=@unlink($p)&&$ok;return $ok;} public function has(string $k):bool{return $this->get($k,new \stdClass()) instanceof \stdClass?false:true;} }
